"use client";

import { useEffect, useState } from "react";
import { useAuth } from "@/context/AuthContext";
import { addPlan, deletePlan, getPlannerItems, updatePlan} from "@/services/plannerService";
import type { PlannerItem, PlannerItemType } from "@/types/planner";

export function usePlanner() {
  const { currentUser } = useAuth();

  const [plannerItems, setPlannerItems] = useState<PlannerItem[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  // Fetch planner items when the current user changes
  useEffect(() => {
    if (!currentUser) {
    setPlannerItems([]);
    setIsLoading(false);
    return;
    }

    setIsLoading(true);
    setError(null);

    try {
    const result = getPlannerItems(currentUser.id);
    setPlannerItems(result);
    } catch (error) {
    console.error(error);
    setError("Failed to load your planner items.");
    } finally {
    setIsLoading(false);
    }
  }, [currentUser]);

  // Function to create a new planner item
  function createPlanner(data: {
    title: string;
    date: string;
    startTime: string;
    endTime: string;
    type :  PlannerItemType;
  }) {
    if (!currentUser) {
      return;
    }

    try {
      addPlan({
        userId: currentUser.id,
        title: data.title,
        date: data.date,
        startTime: data.startTime,
        endTime: data.endTime,
        type: data.type,
      });

      setPlannerItems(getPlannerItems(currentUser.id));
    } catch (error) {
      console.error(error);
      setError("Failed to create planner item.");
    }
  }

  // update planner item
  function updatePlanner(planner: {
    id: number;
    userId: number;
    title: string;
    date: string;
    startTime: string;
    endTime: string;
    type :  PlannerItemType;
  }) {
    if (!currentUser) {
      return;
    }

    try {
      // Update the planner item in the data source
      // Assuming you have a function updatePlan to handle this
      updatePlan(planner.id, {
        title: planner.title,
        date: planner.date,
        startTime: planner.startTime,
        endTime: planner.endTime,
        type: planner.type,
      });

      // Refresh the planner items after the update
      setPlannerItems(getPlannerItems(currentUser.id));
    } catch (error) {
      console.error(error);
      setError("Failed to update planner item.");
    }
  }

  function deletePlanner(id: number) {
    if (!currentUser) {
      return;
    }
    
    try {
      // Assuming you have a function deletePlan to handle this
      deletePlan(id);

      // Refresh the planner items after deletion
      setPlannerItems(getPlannerItems(currentUser.id));
    } catch (error) {
      console.error(error);
      setError("Failed to delete planner item.");
    }
  }

  return {
    plannerItems,
    isLoading,
    error,
    createPlanner,
    updatePlanner,
    deletePlanner,
  };
}
